precision mediump float;
#define PI 3.1415926535897932384626433832795

uniform float time;
uniform float x;
uniform float y;
varying vec2 texCoord;

void main() {
    float v = 0.0;
    vec2 u_k=vec2(x,y);
    vec2 c = texCoord * u_k - u_k/2.0;
    v += sin((c.x+time));
    v += sin((c.y+time)/1.0);
    v += sin((c.x+c.y+time)/2.0);
    c += u_k/2.0 * vec2(sin(time/1.0), cos(time/2.0));
    v += sin(sqrt(c.x*c.x+c.y*c.y+1.0)+time);
    v = v/2.0;
    vec3 col = vec3(0.2, sin(PI*v), cos(PI*v));
    gl_FragColor = vec4(col*.5 + .8, 1);
}

attribute vec3 vPosition;
attribute vec2 attrTexCoord;
attribute vec3 attrVertNormal;
varying vec2 texCoord;
varying vec3 norm;
uniform mat4 projMatrix;
uniform mat4 mvMatrix;
void main()
{
   texCoord=attrTexCoord;
   norm=attrVertNormal;
   gl_Position = projMatrix * mvMatrix * vec4(vPosition,  1.0);
}
